 "content": "def transform(grid):
    # The grid is partitioned by color-4 separator rows/columns into equal cells.
    # Copy the nonempty cell pattern into each empty cell.
    h, w = len(grid), len(grid[0])
    sep = 4
    row_bars = [r for r in range(h) if all(v == sep for v in grid[r])]
    col_bars = [c for c in range(w) if all(grid[r][c] == sep for r in range(h))]
    row_bounds = [-1] + row_bars + [h]
    col_bounds = [-1] + col_bars + [w]
    cells = []
    for ri in range(len(row_bounds)-1):
        r0, r1 = row_bounds[ri]+1, row_bounds[ri+1]
        for ci in range(len(col_bounds)-1):
            c0, c1 = col_bounds[ci]+1, col_bounds[ci+1]
            cells.append((r0,r1,c0,c1))
    source = None
    for r0,r1,c0,c1 in cells:
        if any(grid[r][c] != 9 for r in range(r0,r1) for c in range(c0,c1)):
            source = [[grid[r][c] for c in range(c0,c1)] for r in range(r0,r1)]
            break
    if source is None:
        return [row[:] for row in grid]
    out = [row[:] for row in grid]
    for r0,r1,c0,c1 in cells:
        if r1-r0 == len(source) and c1-c0 == len(source[0]):
            for dr in range(len(source)):
                for dc in range(len(source[0])):
                    out[r0+dr][c0+dc] = source[dr][dc]
    return out
